import{_ as i}from"./chunks/ArticleMetadata.Xa7L4Afm.js";import{_ as r,D as o,o as n,c,I as d,w as h,k as p,a as b,R as u,b as m,e as g}from"./chunks/framework.Dn7lIAzt.js";import"./chunks/md5.vgHT5zCM.js";const _=JSON.parse('{"title":"List、Set 与 Sorted Set","description":"学习 List、Set 与 Sorted Set 的命令、可观察结果、容量与并发边界。","frontmatter":{"title":"List、Set 与 Sorted Set","date":"2026-10-06T00:00:00.000Z","category":"Java课程","tags":["Java","Redis","数据结构"],"description":"学习 List、Set 与 Sorted Set 的命令、可观察结果、容量与并发边界。"},"headers":[],"relativePath":"courses/java/15-Redis/04-List-Set与Sorted-Set.md","filePath":"courses/java/15-Redis/04-List-Set与Sorted-Set.md","lastUpdated":1791252011000}'),k={name:"courses/java/15-Redis/04-List-Set与Sorted-Set.md"},S=p("h1",{id:"list、set-与-sorted-set",tabindex:"-1"},[b("List、Set 与 Sorted Set "),p("a",{class:"header-anchor",href:"#list、set-与-sorted-set","aria-label":'Permalink to "List、Set 与 Sorted Set"'},"​")],-1),v=u(`<h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>掌握本篇独立命令的输入、返回与状态变化，按访问形状选择结构，并为键、返回数量和失败重试设置边界。</p><h2 id="核心知识点" tabindex="-1">核心知识点 <a class="header-anchor" href="#核心知识点" aria-label="Permalink to &quot;核心知识点&quot;">​</a></h2><p>本篇采用 Redis 8 稳定主版本的基础命令语义；官方文档核对日期：2026-10-06，不声明未验证的补丁版本。<a href="https://redis.io/docs/latest/develop/data-types/" target="_blank" rel="noreferrer">官方数据类型</a> 是本章事实依据。</p><p>List 按插入位置保序并允许重复，适合简易队列；Set 无序去重，适合成员判断与集合运算；Sorted Set 按 double score 排序、member 唯一，适合排名。两端 List push/pop、Set 单成员操作通常 O(1)；批次受元素数影响。List 随机访问与遍历 O(N)；Sorted Set 写入通常 O(log N)，范围读取 O(log N + M)。必须控制集合基数和返回条数。</p><p>实验前提：本机独立 Redis 8 服务在 127.0.0.1:6379 运行；通过终端执行 <code>redis-cli -h 127.0.0.1 -p 6379</code> 后在交互提示符输入下面的命令（不是 PowerShell 命令）。有 ACL 时用 <code>--user lab_user --askpass</code> 输入密码。示例注释记录返回，不需要把输出复制成输入；不同客户端的数组排版可能不同。</p><p>每个 H3 都是独立实验。运行每段前、结束后在数据库 0 执行 <code>DEL lab:{core}:q lab:{core}:processing lab:{core}:a lab:{core}:b lab:{core}:z</code>，只清理这些明确的学习 key，不使用通配符、FLUSHDB 或业务库。初始状态：这些 key 均不存在；每段的写入步骤重新创建所需状态。</p><h2 id="常用用法" tabindex="-1">常用用法 <a class="header-anchor" href="#常用用法" aria-label="Permalink to &quot;常用用法&quot;">​</a></h2><h3 id="lpush-把多个元素放入列表左侧以理解插入次序" tabindex="-1"><code>LPUSH</code>：把多个元素放入列表左侧以理解插入次序 <a class="header-anchor" href="#lpush-把多个元素放入列表左侧以理解插入次序" aria-label="Permalink to &quot;\`LPUSH\`：把多个元素放入列表左侧以理解插入次序&quot;">​</a></h3><p>用于把多个元素放入列表左侧以理解插入次序。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>LPUSH lab:{core}:q a b</span></span>
<span class="line"><span>LRANGE lab:{core}:q 0 -1</span></span>
<span class="line"><span># 关键变化：先把 a 放左端，再把 b 放左端，列表变为 b,a。</span></span>
<span class="line"><span># 输出：整数 2，数组为 &quot;b&quot;、&quot;a&quot;。</span></span></code></pre></div><p>多个参数逐个放左端，所以参数顺序会反转；LPUSH 加 LPOP 是栈，LPUSH 加 RPOP 是队列。 官方参考：<a href="https://redis.io/docs/latest/commands/lpush/" target="_blank" rel="noreferrer">LPUSH</a>。</p><h3 id="rpush-在列表右端追加任务以建立先进先出队列" tabindex="-1"><code>RPUSH</code>：在列表右端追加任务以建立先进先出队列 <a class="header-anchor" href="#rpush-在列表右端追加任务以建立先进先出队列" aria-label="Permalink to &quot;\`RPUSH\`：在列表右端追加任务以建立先进先出队列&quot;">​</a></h3><p>用于在列表右端追加任务以建立先进先出队列。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>RPUSH lab:{core}:q a b</span></span>
<span class="line"><span>LRANGE lab:{core}:q 0 -1</span></span>
<span class="line"><span># 关键变化：先追加 a 再追加 b，列表变为 a,b。</span></span>
<span class="line"><span># 输出：整数 2，数组为 &quot;a&quot;、&quot;b&quot;。</span></span></code></pre></div><p>搭配 LPOP 得到 FIFO；List 没有自动确认和重投机制。 官方参考：<a href="https://redis.io/docs/latest/commands/rpush/" target="_blank" rel="noreferrer">RPUSH</a>。</p><h3 id="lpop-从左端移除一个元素并观察剩余队列" tabindex="-1"><code>LPOP</code>：从左端移除一个元素并观察剩余队列 <a class="header-anchor" href="#lpop-从左端移除一个元素并观察剩余队列" aria-label="Permalink to &quot;\`LPOP\`：从左端移除一个元素并观察剩余队列&quot;">​</a></h3><p>用于从左端移除一个元素并观察剩余队列。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>RPUSH lab:{core}:q a b</span></span>
<span class="line"><span>LPOP lab:{core}:q</span></span>
<span class="line"><span>LRANGE lab:{core}:q 0 -1</span></span>
<span class="line"><span># 关键变化：列表先保存 a,b；移除左端 a 后剩余 b。</span></span>
<span class="line"><span># 输出：整数 2、&quot;a&quot;，剩余数组为 &quot;b&quot;。</span></span></code></pre></div><p>空 key 返回 nil；取走后客户端崩溃会丢失处理机会，可靠交付应另设 processing 列表或使用 Stream 消费组。 官方参考：<a href="https://redis.io/docs/latest/commands/lpop/" target="_blank" rel="noreferrer">LPOP</a>。</p><h3 id="rpop-从右端移除一个元素并观察栈式顺序" tabindex="-1"><code>RPOP</code>：从右端移除一个元素并观察栈式顺序 <a class="header-anchor" href="#rpop-从右端移除一个元素并观察栈式顺序" aria-label="Permalink to &quot;\`RPOP\`：从右端移除一个元素并观察栈式顺序&quot;">​</a></h3><p>用于从右端移除一个元素并观察栈式顺序。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>RPUSH lab:{core}:q a b</span></span>
<span class="line"><span>RPOP lab:{core}:q</span></span>
<span class="line"><span>LRANGE lab:{core}:q 0 -1</span></span>
<span class="line"><span># 关键变化：列表先保存 a,b；移除右端 b 后剩余 a。</span></span>
<span class="line"><span># 输出：整数 2、&quot;b&quot;，剩余数组为 &quot;a&quot;。</span></span></code></pre></div><p>RPUSH 与 RPOP 组合是后进先出。 官方参考：<a href="https://redis.io/docs/latest/commands/rpop/" target="_blank" rel="noreferrer">RPOP</a>。</p><h3 id="lrange-按闭区间读取有限数量的列表元素" tabindex="-1"><code>LRANGE</code>：按闭区间读取有限数量的列表元素 <a class="header-anchor" href="#lrange-按闭区间读取有限数量的列表元素" aria-label="Permalink to &quot;\`LRANGE\`：按闭区间读取有限数量的列表元素&quot;">​</a></h3><p>用于按闭区间读取有限数量的列表元素。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>RPUSH lab:{core}:q a b c</span></span>
<span class="line"><span>LRANGE lab:{core}:q 0 1</span></span>
<span class="line"><span># 关键变化：列表保存 a,b,c；闭区间 0..1 返回 a,b。</span></span>
<span class="line"><span># 输出：整数 3，数组为 &quot;a&quot;、&quot;b&quot;。</span></span></code></pre></div><p>stop 包含末端，-1 指末尾；生产禁止无界拉取巨大列表。复杂度与偏移和返回长度有关。 官方参考：<a href="https://redis.io/docs/latest/commands/lrange/" target="_blank" rel="noreferrer">LRANGE</a>。</p><h3 id="llen-读取队列长度以观察积压数量" tabindex="-1"><code>LLEN</code>：读取队列长度以观察积压数量 <a class="header-anchor" href="#llen-读取队列长度以观察积压数量" aria-label="Permalink to &quot;\`LLEN\`：读取队列长度以观察积压数量&quot;">​</a></h3><p>用于读取队列长度以观察积压数量。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>RPUSH lab:{core}:q a b</span></span>
<span class="line"><span>LLEN lab:{core}:q</span></span>
<span class="line"><span># 关键变化：q 追加两个元素，读取当前积压数量为 2。</span></span>
<span class="line"><span># 输出：整数 2、整数 2。</span></span></code></pre></div><p>O(1)，长度是等待元素数，不含已弹出但尚未完成的任务。 官方参考：<a href="https://redis.io/docs/latest/commands/llen/" target="_blank" rel="noreferrer">LLEN</a>。</p><h3 id="blpop-等待空队列出现元素并限定阻塞超时" tabindex="-1"><code>BLPOP</code>：等待空队列出现元素并限定阻塞超时 <a class="header-anchor" href="#blpop-等待空队列出现元素并限定阻塞超时" aria-label="Permalink to &quot;\`BLPOP\`：等待空队列出现元素并限定阻塞超时&quot;">​</a></h3><p>用于等待空队列出现元素并限定阻塞超时。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>BLPOP lab:{core}:q 1</span></span>
<span class="line"><span># 关键变化：连接等待约 1 秒，队列仍为空。</span></span>
<span class="line"><span># 输出：空队列在约 1 秒后返回 (nil)。</span></span></code></pre></div><p>阻塞当前客户端连接，其他连接可继续工作；0 表示无限等待。使用专用连接与取消策略，Cluster 多 key 必须同槽，不在普通共享连接上无期限等待。 官方参考：<a href="https://redis.io/docs/latest/commands/blpop/" target="_blank" rel="noreferrer">BLPOP</a>。</p><h3 id="lmove-原子把任务转移到处理列表以保留失败恢复线索" tabindex="-1"><code>LMOVE</code>：原子把任务转移到处理列表以保留失败恢复线索 <a class="header-anchor" href="#lmove-原子把任务转移到处理列表以保留失败恢复线索" aria-label="Permalink to &quot;\`LMOVE\`：原子把任务转移到处理列表以保留失败恢复线索&quot;">​</a></h3><p>用于原子把任务转移到处理列表以保留失败恢复线索。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>RPUSH lab:{core}:q job-1</span></span>
<span class="line"><span>LMOVE lab:{core}:q lab:{core}:processing LEFT RIGHT</span></span>
<span class="line"><span>LRANGE lab:{core}:processing 0 -1</span></span>
<span class="line"><span># 关键变化：q 创建 job-1；转移后 q 消失，processing 保存 job-1。</span></span>
<span class="line"><span># 输出：整数 1、&quot;job-1&quot;，处理列表为 &quot;job-1&quot;。</span></span></code></pre></div><p>两键同槽；转移只是可靠队列的一步，处理成功需确认删除，失败需回收与幂等。LMOVE 不阻塞，阻塞版本是 BLMOVE。 官方参考：<a href="https://redis.io/docs/latest/commands/lmove/" target="_blank" rel="noreferrer">LMOVE</a>。</p><h3 id="sadd-向无序集合添加成员并观察去重" tabindex="-1"><code>SADD</code>：向无序集合添加成员并观察去重 <a class="header-anchor" href="#sadd-向无序集合添加成员并观察去重" aria-label="Permalink to &quot;\`SADD\`：向无序集合添加成员并观察去重&quot;">​</a></h3><p>用于向无序集合添加成员并观察去重。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red blue red</span></span>
<span class="line"><span>SCARD lab:{core}:a</span></span>
<span class="line"><span># 关键变化：a 新增 red、blue，重复 red 没有再增加成员。</span></span>
<span class="line"><span># 输出：整数 2、整数 2。</span></span></code></pre></div><p>返回新成员数；不维护插入顺序。 官方参考：<a href="https://redis.io/docs/latest/commands/sadd/" target="_blank" rel="noreferrer">SADD</a>。</p><h3 id="sismember-判断成员是否在精确去重集合内" tabindex="-1"><code>SISMEMBER</code>：判断成员是否在精确去重集合内 <a class="header-anchor" href="#sismember-判断成员是否在精确去重集合内" aria-label="Permalink to &quot;\`SISMEMBER\`：判断成员是否在精确去重集合内&quot;">​</a></h3><p>用于判断成员是否在精确去重集合内。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red</span></span>
<span class="line"><span>SISMEMBER lab:{core}:a red</span></span>
<span class="line"><span>SISMEMBER lab:{core}:a blue</span></span>
<span class="line"><span># 关键变化：a 新增 red；red 存在而 blue 不存在。</span></span>
<span class="line"><span># 输出：整数 1、整数 1、整数 0。</span></span></code></pre></div><p>精确成员判断，适合标签与访问名单；高基数需要相应内存。 官方参考：<a href="https://redis.io/docs/latest/commands/sismember/" target="_blank" rel="noreferrer">SISMEMBER</a>。</p><h3 id="smembers-枚举小集合的全部成员以检查内容" tabindex="-1"><code>SMEMBERS</code>：枚举小集合的全部成员以检查内容 <a class="header-anchor" href="#smembers-枚举小集合的全部成员以检查内容" aria-label="Permalink to &quot;\`SMEMBERS\`：枚举小集合的全部成员以检查内容&quot;">​</a></h3><p>用于枚举小集合的全部成员以检查内容。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red blue</span></span>
<span class="line"><span>SMEMBERS lab:{core}:a</span></span>
<span class="line"><span># 关键变化：a 保存两个唯一成员，枚举结果不承诺顺序。</span></span>
<span class="line"><span># 输出：整数 2；成员为 red、blue，顺序不保证。</span></span></code></pre></div><p>O(N)，大集合应改用 SSCAN 并处理重复与并发变化。 官方参考：<a href="https://redis.io/docs/latest/commands/smembers/" target="_blank" rel="noreferrer">SMEMBERS</a>。</p><h3 id="scard-读取精确集合基数以核对去重结果" tabindex="-1"><code>SCARD</code>：读取精确集合基数以核对去重结果 <a class="header-anchor" href="#scard-读取精确集合基数以核对去重结果" aria-label="Permalink to &quot;\`SCARD\`：读取精确集合基数以核对去重结果&quot;">​</a></h3><p>用于读取精确集合基数以核对去重结果。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red red blue</span></span>
<span class="line"><span>SCARD lab:{core}:a</span></span>
<span class="line"><span># 关键变化：a 接收 red、red、blue，去重后数量为 2。</span></span>
<span class="line"><span># 输出：整数 2、整数 2。</span></span></code></pre></div><p>O(1)，精确计数但需要保存全部成员；只需大规模近似 UV 时考虑 HyperLogLog。 官方参考：<a href="https://redis.io/docs/latest/commands/scard/" target="_blank" rel="noreferrer">SCARD</a>。</p><h3 id="srem-移除明确成员并观察不存在成员的计数" tabindex="-1"><code>SREM</code>：移除明确成员并观察不存在成员的计数 <a class="header-anchor" href="#srem-移除明确成员并观察不存在成员的计数" aria-label="Permalink to &quot;\`SREM\`：移除明确成员并观察不存在成员的计数&quot;">​</a></h3><p>用于移除明确成员并观察不存在成员的计数。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red blue</span></span>
<span class="line"><span>SREM lab:{core}:a red missing</span></span>
<span class="line"><span>SCARD lab:{core}:a</span></span>
<span class="line"><span># 关键变化：a 新增 red、blue；移除 red 成功，missing 无变化，剩余 blue。</span></span>
<span class="line"><span># 输出：整数 2、整数 1、整数 1。</span></span></code></pre></div><p>最后一个成员移除后 key 消失。 官方参考：<a href="https://redis.io/docs/latest/commands/srem/" target="_blank" rel="noreferrer">SREM</a>。</p><h3 id="sinter-计算共同成员以筛选共享标签" tabindex="-1"><code>SINTER</code>：计算共同成员以筛选共享标签 <a class="header-anchor" href="#sinter-计算共同成员以筛选共享标签" aria-label="Permalink to &quot;\`SINTER\`：计算共同成员以筛选共享标签&quot;">​</a></h3><p>用于计算共同成员以筛选共享标签。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red blue</span></span>
<span class="line"><span>SADD lab:{core}:b blue green</span></span>
<span class="line"><span>SINTER lab:{core}:a lab:{core}:b</span></span>
<span class="line"><span># 关键变化：a 保存 red、blue，b 保存 blue、green；交集读取 blue。</span></span>
<span class="line"><span># 输出：两个整数 2；交集为 blue。</span></span></code></pre></div><p>最坏 O(N*M)，N 是最小集合大小、M 是集合数；多键同槽且需要限制集合规模。 官方参考：<a href="https://redis.io/docs/latest/commands/sinter/" target="_blank" rel="noreferrer">SINTER</a>。</p><h3 id="sunion-计算去重并集以合并成员名单" tabindex="-1"><code>SUNION</code>：计算去重并集以合并成员名单 <a class="header-anchor" href="#sunion-计算去重并集以合并成员名单" aria-label="Permalink to &quot;\`SUNION\`：计算去重并集以合并成员名单&quot;">​</a></h3><p>用于计算去重并集以合并成员名单。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red blue</span></span>
<span class="line"><span>SADD lab:{core}:b blue green</span></span>
<span class="line"><span>SUNION lab:{core}:a lab:{core}:b</span></span>
<span class="line"><span># 关键变化：a 与 b 分别创建两成员，并集去重后返回三成员。</span></span>
<span class="line"><span># 输出：两个整数 2；并集为 red、blue、green，顺序不保证。</span></span></code></pre></div><p>O(所有输入成员总数)，输出可能远大于单个输入；Cluster 多键同槽。 官方参考：<a href="https://redis.io/docs/latest/commands/sunion/" target="_blank" rel="noreferrer">SUNION</a>。</p><h3 id="sdiff-计算有方向的差集以找出未覆盖成员" tabindex="-1"><code>SDIFF</code>：计算有方向的差集以找出未覆盖成员 <a class="header-anchor" href="#sdiff-计算有方向的差集以找出未覆盖成员" aria-label="Permalink to &quot;\`SDIFF\`：计算有方向的差集以找出未覆盖成员&quot;">​</a></h3><p>用于计算有方向的差集以找出未覆盖成员。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>SADD lab:{core}:a red blue</span></span>
<span class="line"><span>SADD lab:{core}:b blue green</span></span>
<span class="line"><span>SDIFF lab:{core}:a lab:{core}:b</span></span>
<span class="line"><span># 关键变化：a 与 b 分别创建两成员，从 a 排除 b 的成员后返回 red。</span></span>
<span class="line"><span># 输出：两个整数 2；差集为 red。</span></span></code></pre></div><p>a-b 与 b-a 不同；O(输入成员总数)，Cluster 多键同槽。 官方参考：<a href="https://redis.io/docs/latest/commands/sdiff/" target="_blank" rel="noreferrer">SDIFF</a>。</p><h3 id="zadd-给唯一成员写入分数以建立排名" tabindex="-1"><code>ZADD</code>：给唯一成员写入分数以建立排名 <a class="header-anchor" href="#zadd-给唯一成员写入分数以建立排名" aria-label="Permalink to &quot;\`ZADD\`：给唯一成员写入分数以建立排名&quot;">​</a></h3><p>用于给唯一成员写入分数以建立排名。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>ZADD lab:{core}:z 10 Ann 20 Bob</span></span>
<span class="line"><span>ZADD lab:{core}:z 30 Ann</span></span>
<span class="line"><span>ZSCORE lab:{core}:z Ann</span></span>
<span class="line"><span># 关键变化：z 新增 Ann=10、Bob=20；随后 Ann 更新为 30，没有新增 member。</span></span>
<span class="line"><span># 输出：整数 2、整数 0、&quot;30&quot;。</span></span></code></pre></div><p>默认返回新成员数；同 member 更新分数。double 精确整数范围为 ±2^53，同分按 member 字节的字典序排列。 官方参考：<a href="https://redis.io/docs/latest/commands/zadd/" target="_blank" rel="noreferrer">ZADD</a>。</p><h3 id="zrange-按排名或分数读取有界的排行榜" tabindex="-1"><code>ZRANGE</code>：按排名或分数读取有界的排行榜 <a class="header-anchor" href="#zrange-按排名或分数读取有界的排行榜" aria-label="Permalink to &quot;\`ZRANGE\`：按排名或分数读取有界的排行榜&quot;">​</a></h3><p>用于按排名或分数读取有界的排行榜。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>ZADD lab:{core}:z 10 Ann 20 Bob</span></span>
<span class="line"><span>ZRANGE lab:{core}:z 0 1 REV WITHSCORES</span></span>
<span class="line"><span>ZRANGE lab:{core}:z 10 20 BYSCORE WITHSCORES</span></span>
<span class="line"><span># 关键变化：z 保存 Ann=10、Bob=20；读取降序排名和升序分数区间。</span></span>
<span class="line"><span># 输出：整数 2；第一数组为 Bob,20,Ann,10，第二为 Ann,10,Bob,20。</span></span></code></pre></div><p>rank 从 0 开始，两端包含；REV 倒序，BYSCORE 改为分数区间。优先统一 ZRANGE 选项而非旧 ZREVRANGE；O(log N + M)。 官方参考：<a href="https://redis.io/docs/latest/commands/zrange/" target="_blank" rel="noreferrer">ZRANGE</a>。</p><h3 id="zscore-读取单个成员当前的分数" tabindex="-1"><code>ZSCORE</code>：读取单个成员当前的分数 <a class="header-anchor" href="#zscore-读取单个成员当前的分数" aria-label="Permalink to &quot;\`ZSCORE\`：读取单个成员当前的分数&quot;">​</a></h3><p>用于读取单个成员当前的分数。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>ZADD lab:{core}:z 10 Ann</span></span>
<span class="line"><span>ZSCORE lab:{core}:z Ann</span></span>
<span class="line"><span>ZSCORE lab:{core}:z missing</span></span>
<span class="line"><span># 关键变化：z 保存 Ann=10，missing 不存在，读取区分分数与 nil。</span></span>
<span class="line"><span># 输出：整数 1、&quot;10&quot;、(nil)。</span></span></code></pre></div><p>O(1)，零分数和不存在 member 不同。 官方参考：<a href="https://redis.io/docs/latest/commands/zscore/" target="_blank" rel="noreferrer">ZSCORE</a>。</p><h3 id="zrank-读取成员从零开始的升序排名" tabindex="-1"><code>ZRANK</code>：读取成员从零开始的升序排名 <a class="header-anchor" href="#zrank-读取成员从零开始的升序排名" aria-label="Permalink to &quot;\`ZRANK\`：读取成员从零开始的升序排名&quot;">​</a></h3><p>用于读取成员从零开始的升序排名。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>ZADD lab:{core}:z 10 Ann 20 Bob</span></span>
<span class="line"><span>ZRANK lab:{core}:z Bob</span></span>
<span class="line"><span># 关键变化：z 保存两成员；升序位置 Ann=0、Bob=1。</span></span>
<span class="line"><span># 输出：整数 2、整数 1。</span></span></code></pre></div><p>O(log N)，面向用户显示名次时通常加 1；降序排名使用 ZREVRANK。 官方参考：<a href="https://redis.io/docs/latest/commands/zrank/" target="_blank" rel="noreferrer">ZRANK</a>。</p><h3 id="zincrby-原子调整成员分数并观察累计排名依据" tabindex="-1"><code>ZINCRBY</code>：原子调整成员分数并观察累计排名依据 <a class="header-anchor" href="#zincrby-原子调整成员分数并观察累计排名依据" aria-label="Permalink to &quot;\`ZINCRBY\`：原子调整成员分数并观察累计排名依据&quot;">​</a></h3><p>用于原子调整成员分数并观察累计排名依据。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>ZADD lab:{core}:z 10 Ann</span></span>
<span class="line"><span>ZINCRBY lab:{core}:z 5 Ann</span></span>
<span class="line"><span>ZSCORE lab:{core}:z Ann</span></span>
<span class="line"><span># 关键变化：Ann 分数从 10 累加 5 后变为 15。</span></span>
<span class="line"><span># 输出：整数 1、&quot;15&quot;、&quot;15&quot;。</span></span></code></pre></div><p>不能用浮点分数存精确财务金额；写超时盲重试可能重复加分。 官方参考：<a href="https://redis.io/docs/latest/commands/zincrby/" target="_blank" rel="noreferrer">ZINCRBY</a>。</p><h3 id="zrem-移除排名成员并确认后续查询缺失" tabindex="-1"><code>ZREM</code>：移除排名成员并确认后续查询缺失 <a class="header-anchor" href="#zrem-移除排名成员并确认后续查询缺失" aria-label="Permalink to &quot;\`ZREM\`：移除排名成员并确认后续查询缺失&quot;">​</a></h3><p>用于移除排名成员并确认后续查询缺失。</p><div class="language-redis vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">redis</span><pre class="shiki shiki-themes github-light github-dark-dimmed vp-code"><code><span class="line"><span># 初始：本段实验 key 已按上文清理，数据库 0 内不存在。</span></span>
<span class="line"><span>ZADD lab:{core}:z 10 Ann</span></span>
<span class="line"><span>ZREM lab:{core}:z Ann</span></span>
<span class="line"><span>ZSCORE lab:{core}:z Ann</span></span>
<span class="line"><span># 关键变化：Ann 创建后被移除，z 最后一个成员消失，后续读取为 nil。</span></span>
<span class="line"><span># 输出：整数 1、整数 1、(nil)。</span></span></code></pre></div><p>GEO 索引也使用 ZREM 删除地点，但不要对 GEO 索引任意改写 score。 官方参考：<a href="https://redis.io/docs/latest/commands/zrem/" target="_blank" rel="noreferrer">ZREM</a>。</p><h2 id="易混点" tabindex="-1">易混点 <a class="header-anchor" href="#易混点" aria-label="Permalink to &quot;易混点&quot;">​</a></h2><p>队列的顺序、成功处理和可靠交付是三个独立契约；弹出不等于完成任务。集合没有固定返回顺序，同分排名也需解释 member 的字典序。</p><h2 id="课后小问" tabindex="-1">课后小问 <a class="header-anchor" href="#课后小问" aria-label="Permalink to &quot;课后小问&quot;">​</a></h2><ol><li>本篇怎样验证示例没有依赖上一次实验？</li></ol><p>答案：每个小节先清理明确实验 key，再按本段重建输入，读回结果后清理；连接与认证例按注明的连接前置条件执行。</p><ol start="2"><li>网络超时后能否直接重试写操作？</li></ol><p>答案：不能由超时推断服务端未执行。对计数、入队、事件追加等写操作应设计幂等、重试上限与恢复路径。</p><h2 id="本节小结" tabindex="-1">本节小结 <a class="header-anchor" href="#本节小结" aria-label="Permalink to &quot;本节小结&quot;">​</a></h2><p>按输入与输出验证命令语义，再评估数据量、阻塞时间、精度和失败路径；实验清理只针对明确学习 key。</p><h2 id="快速回顾" tabindex="-1">快速回顾 <a class="header-anchor" href="#快速回顾" aria-label="Permalink to &quot;快速回顾&quot;">​</a></h2><p>能根据本篇 H3 搜索命令、重建初始状态、解释返回值，并说明哪些边界需要客户端或业务协议补齐。</p>`,107);function q(a,f,R,P,y,A){const l=i,t=o("ClientOnly");return n(),c("div",null,[S,d(t,null,{default:h(()=>{var s,e;return[(((s=a.$frontmatter)==null?void 0:s.aside)??!0)&&(((e=a.$frontmatter)==null?void 0:e.showArticleMetadata)??!0)?(n(),m(l,{key:0,article:a.$frontmatter},null,8,["article"])):g("",!0)]}),_:1}),v])}const L=r(k,[["render",q]]);export{_ as __pageData,L as default};
